Ext._define('rh.digitaldocument.attachment.Window', {
    extend: 'rh.digitaldocument.Window',
    rest: 'rh.digitaldocument.attachment.Restful',

    getFormPanel: function(cfg) {
        if(!this._formPanel)
            this._formPanel = Ext._create('Ext.form.FormPanel', {
                border: false,
                frame: true,
                items: [
                    this.getEmployeeField(),
                    {
                        maxLength: 100,
                        allowBlank: false,
                        fieldLabel: "Nome *",
                        name: "name",
                        xtype: "textfield",
                        width: 400
                    },
                    {
                        xtype: 'ged-fileuploadfield',
                        fieldLabel: 'Arquivo *',
                        allowBlank: true,
                        name: 'file',
                        hiddenName: 'file',
                        value: cfg.values.file,
                        listeners: {
                            scope: this,
                            afterchange: function(field, value, oldVal)
                            { /* Callback criado devido ao evento change não se comportar como esperado com composite field */

                                var titleField = this.find('name', 'name')[0],
                                    filename = value.split('/').pop();

                                titleField.setValue(filename);
                                titleField.focus();
                            }
                        }
                    },
                    // this.getDocumentTypeChoiceField(),
                ]
            });
        return this._formPanel;
    },

});